  const p = input[idx++];
  parent[v] = p;
  nextSibling[v] = firstChild[p];
  firstChild[p] = v;
}

const size = new Int32Array(N + 1);
const heavy = new Int32Array(N + 1);
size.fill(1);

for (let v = N; v >= 2; v--) {
  const p = parent[v];
  size[p] += size[v];
  if (heavy[p] === 0 || size[v] > size[heavy[p]]) {
    heavy[p] = v;
  }
}

const head = new Int32Array(N + 1);
const pos = new Int32Array(N + 1);
const nodeAt = new Int32Array(N);
const starts = [1];
let timer = 0;

while (starts.length > 0) {
  const start = starts.pop();
  let v = start;

  while (v !== 0) {
    head[v] = start;
    pos[v] = timer;
    nodeAt[timer++] = v;

    for (let child = firstChild[v]; child !== 0; child = nextSibling[child]) {
      if (child !== heavy[v]) starts.push(child);
    }

    v = heavy[v];
  }
}

const LOG = 17;
const up = Array.from({ length: LOG }, () => new Int32Array(N + 1));
for (let v = 1; v <= N; v++) {
  up[0][v] = v === 1 ? 1 : parent[v];
}
for (let j = 1; j < LOG; j++) {
  const prev = up[j - 1];
  const cur = up[j];
  for (let v = 1; v <= N; v++) cur[v] = prev[prev[v]];
}

function ancestor(v, distance) {
  let bit = 0;
  while (distance > 0) {
    if (distance & 1) v = up[bit][v];
    distance = Math.floor(distance / 2);
    bit++;
  }
  return v;
}

const segSum = new Int32Array(4 * N);
const lazyClear = new Uint8Array(4 * N);

function push(node) {
  if (lazyClear[node]) {
    const left = node * 2;
    const right = left + 1;
    segSum[left] = 0;
    segSum[right] = 0;
    lazyClear[left] = 1;
    lazyClear[right] = 1;
    lazyClear[node] = 0;
  }
}

function clearRange(node, left, right, ql, qr) {
  if (ql <= left && right <= qr) {
    segSum[node] = 0;
    lazyClear[node] = 1;
    return;
  }

  push(node);
  const mid = (left + right) >> 1;
  if (ql <= mid) clearRange(node * 2, left, mid, ql, qr);
  if (qr > mid) clearRange(node * 2 + 1, mid + 1, right, ql, qr);
  segSum[node] = segSum[node * 2] + segSum[node * 2 + 1];
}

function setPoint(node, left, right, index) {
  if (left === right) {
    segSum[node] = 1;
    lazyClear[node] = 0;
    return;
  }

  push(node);
  const mid = (left + right) >> 1;
  if (index <= mid) setPoint(node * 2, left, mid, index);
  else setPoint(node * 2 + 1, mid + 1, right, index);
  segSum[node] = segSum[node * 2] + segSum[node * 2 + 1];
}

