  if (ql <= left && right <= qr) return segSum[node];
  push(node);
  const mid = (left + right) >> 1;
  let result = 0;
  if (ql <= mid) result += rangeSum(node * 2, left, mid, ql, qr);
  if (qr > mid) result += rangeSum(node * 2 + 1, mid + 1, right, ql, qr);
  return result;
}

let remainingRank;

function findKthRightRec(node, left, right, ql, qr) {
  if (qr < left || right < ql) return -1;

  if (ql <= left && right <= qr && segSum[node] < remainingRank) {
    remainingRank -= segSum[node];
    return -1;
  }

  if (left === right) return segSum[node] === 1 ? left : -1;

  push(node);
  const mid = (left + right) >> 1;
  let found = findKthRightRec(node * 2 + 1, mid + 1, right, ql, qr);
  if (found !== -1) return found;
  return findKthRightRec(node * 2, left, mid, ql, qr);
}

function findKthRight(ql, qr, rank) {
  remainingRank = rank;
  return findKthRightRec(1, 0, N - 1, ql, qr);
}

function countOnPath(v) {
  let count = 0;
  while (head[v] !== head[1]) {
    count += rangeSum(1, 0, N - 1, pos[head[v]], pos[v]);
    v = parent[head[v]];
  }
  count += rangeSum(1, 0, N - 1, pos[1], pos[v]);
  return count;
}

function selectOnPath(v, rank) {
  while (head[v] !== head[1]) {
    const left = pos[head[v]];
    const right = pos[v];
    const count = rangeSum(1, 0, N - 1, left, right);

    if (rank <= count) {
      return nodeAt[findKthRight(left, right, rank)];
    }
    rank -= count;
    v = parent[head[v]];
  }

  const left = pos[1];
  const right = pos[v];
  return nodeAt[findKthRight(left, right, rank)];
}

const Q = input[idx++];
const output = [];

for (let i = 0; i < Q; i++) {
  const type = input[idx++];

  if (type === 1) {
    const v = input[idx++];
    const k = input[idx++];
    const count = countOnPath(v);

    if (k <= count) {
      output.push(String(selectOnPath(v, k)));
    } else if (count === 0) {
      output.push(String(ancestor(v, k)));
    } else {
      const earliestRecord = selectOnPath(v, count);
      output.push(String(ancestor(earliestRecord, k - count)));
    }
  } else {
    const v = input[idx++];
    const left = pos[v];
    const right = left + size[v] - 1;
    clearRange(1, 0, N - 1, left, right);
    setPoint(1, 0, N - 1, pos[v]);
  }
}

